+ * Throws if the URL uses plaintext HTTP.
+ */
+export function assertSecureUrl(url: string): void {
+ // Relative URLs are always allowed
+ if (url.startsWith('/') || url.startsWith('./') || url.startsWith('../')) {
+ return;
+ }
+
+ // Data URLs are allowed
