+        _meta: {
+          'cardano402/endpoint': {
+            method: endpoint.method,
+            path: endpoint.path,
+            network: endpoint.network,
+            asset: endpoint.asset,
+            amount: endpoint.amount,
+            payTo: endpoint.payTo,
+          },

