+        `amount ${args.amount.toString()} would push 24h spend from ${used.toString()} to ${(used + args.amount).toString()}, ` +
+          `over the ${this.maxPerDay.toString()} lovelace per-day cap`,
+        'per_day'
+      );
+    }
+  }
