+ user_action: 'PAY_NOW',
+ }
+ });
+
+ try {
+ const order = await client.execute(request);
+ db.run(`INSERT INTO purchases (id, patch_id, paypal_order_id, status, cli_session_id) VALUES (?, ?, ?, ?, ?)`,
+ [purchaseId, patchId, order.result.id, 'CREATED', cliSessionId],
