+ res.status(404).json({ error: "Patch file not found." });
+ } else {
+ console.error("Error decrypting patch:", error);
+ res.status(500).json({ error: "Could not decrypt patch." });
+ }
+ }
+ });
+});
+
+app.get('/', (req, res) => {
+ res.send('Backend-in-a-Box is running!');
+});
